    getMetrics: {
        parameters: {
            query?: {
                /**
                 * @description Start of the window, inclusive. Defaults to 24 hours ago.
                 *     Rows older than `metricsRetentionDays` are gone, so a
                 *     `since` beyond it returns what survived and sets
                 *     `truncated`.
                 */
                since?: string;
                /** @description End of the window, exclusive. Defaults to now. */
                until?: string;
                /** @description Restrict to one requested model id. */
                model?: string;
                /** @description Restrict to one inference-driver by name. */
                driver?: string;
                /**
                 * @description `none` (default) returns one group per dimension tuple over
                 *     the whole window. `hour` additionally splits each group by
                 *     hour, which is what a history chart reads.
                 *
                 *     Both are computed from **raw rows**, so both are bounded by
                 *     `metricsRetentionDays`. Hourly rollups are written and kept
                 *     past retention, but they are not served here and deliberately
                 *     so: a rollup can carry sums and a max, and a percentile
                 *     cannot be reconstructed from those. Serving a mean through a
                 *     field named `p50` would be a quieter error than serving
                 *     nothing.
                 */
                bucket?: "none" | "hour";
                /**
                 * @description `backend` (default) groups by the full dimension tuple
                 *     (model, driver, runtime, node, backend) — the comparison
                 *     table's shape. `model` collapses the backend dimensions,
                 *     answering "how is this model doing" across replicas and
                 *     cascades. `total` collapses everything into one group per
                 *     bucket — the shape an overview chart or a stat tile reads.
                 *
                 *     This parameter exists because percentiles cannot be
                 *     recombined client-side: a caller holding per-backend groups
                 *     can sum their `requests`, but the install-wide p90 is not
                 *     computable from per-group p90s. The coarser grains are
                 *     computed here over the bucket's raw rows, so their
                 *     percentiles are real percentiles rather than a merge that
                 *     flatters whichever group was busiest.
                 */
                groupBy?: "backend" | "model" | "total";
            };
            header?: never;
            path?: never;
            cookie?: never;
        };
        requestBody?: never;
        responses: {
            /** @description Aggregates over the window. */
            200: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": components["schemas"]["MetricsSummary"];
                };
            };
            /**
             * @description Metrics are disabled (`metricsEnabled: false`) or the store
             *     could not be opened. Distinguished from an empty window,
             *     which is a 200 with no groups.
             */
            503: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/problem+json": components["schemas"]["Problem"];
                };
            };
        };
    };
    getMetricRequests: {
        parameters: {
            query?: {
                limit?: number;
                /**
                 * @description `nextCursor` from a previous page. Opaque; encodes the
                 *     position rather than an offset, so a page is stable while
                 *     new requests arrive.
                 */
                cursor?: string;
                model?: string;
                /**
                 * @description Restrict to one outcome. `error` and `cascaded` are the two
                 *     worth filtering for; `cascaded` means `attempts > 1`
                 *     whether or not the request eventually succeeded.
                 */
                outcome?: "served" | "error" | "cascaded";
            };
            header?: never;
            path?: never;
            cookie?: never;
        };
        requestBody?: never;
        responses: {
            /** @description One page of retained requests. */
            200: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": components["schemas"]["MetricRequestPage"];
                };
            };
            /** @description Metrics are disabled or the store could not be opened. */
            503: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/problem+json": components["schemas"]["Problem"];
                };
            };
        };
    };
